class DistanceLimitedPathsExist {
public:
    int LOG = 18;
    vector<vector<int>> up;
    vector<int> depth;
    vector<int> val;
    vector<int> parent;
    int find(int i) {
        return parent[i] == i ? i : parent[i] = find(parent[i]);
    }
    DistanceLimitedPathsExist(int n, vector<vector<int>>& edgeList) {
        sort(edgeList.begin(), edgeList.end(), [](const auto& a, const auto& b) {
            return a[2] < b[2];
        });
        parent.resize(2 * n);
        iota(parent.begin(), parent.end(), 0);
        val.resize(2 * n, 0);
        int nodeCount = n;
        vector<vector<int>> adj(2 * n);
        for (const auto& e : edgeList) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru != rv) {
                int newNode = nodeCount++;
                val[newNode] = e[2];
                parent[ru] = newNode;
                parent[rv] = newNode;
                adj[newNode].push_back(ru);
                adj[newNode].push_back(rv);
            }
        }
        up.assign(nodeCount, vector<int>(LOG, 0));
        depth.assign(nodeCount, 0);
        vector<bool> visited(nodeCount, false);
        for (int i = nodeCount - 1; i >= 0; i--) {
            if (find(i) == i && !visited[i]) {
                vector<int> st = {i};
                visited[i] = true;
                while (!st.empty()) {
                    int curr = st.back(); st.pop_back();
                    for (int ch : adj[curr]) {
                        if (!visited[ch]) {
                            visited[ch] = true;
                            depth[ch] = depth[curr] + 1;
                            up[ch][0] = curr;
                            for (int k = 1; k < LOG; k++) {
                                up[ch][k] = up[up[ch][k - 1]][k - 1];
                            }
                            st.push_back(ch);
                        }
                    }
                }
            }
        }
    }
    bool query(int p, int q, int limit) {
        if (find(p) != find(q)) return false;
        if (depth[p] < depth[q]) swap(p, q);
        for (int k = LOG - 1; k >= 0; k--) {
